"use strict";(self.webpackChunkvuepress_theme_reco_demo=self.webpackChunkvuepress_theme_reco_demo||[]).push([[9062],{4568:(n,s,e)=>{e.r(s),e.d(s,{comp:()=>a,data:()=>t});var i=e(641);const l={},a=(0,e(6262).A)(l,[["render",function(n,s){return(0,i.uX)(),(0,i.CE)("div",null,s[0]||(s[0]=[(0,i.Fv)('<p>防抖（Debounce）和节流（Throttle）是前端开发中常用的两种优化手段，主要用于控制高频率触发的事件，避免过多的计算或者操作影响性能。</p><h3 id="防抖-debounce" tabindex="-1"><a class="header-anchor" href="#防抖-debounce"><span>防抖（Debounce）</span></a></h3><p>在事件被触发后，延迟指定时间才执行事件的处理函数，如果这段时间内时间再次被触发，则重新计时。</p><p><strong>工作原理：</strong></p><ol><li>当事件被处罚时，设定一个定时器</li><li>如果在定时器到期前事件再次被处罚，则清除之前的定时器并重新设置</li><li>只有当事件停止触发切定时器到期后，目标函数才会执行</li></ol><p><strong>典型应用场景：</strong></p><ul><li>搜索框输入（等待用户停止输入后再发送请求）</li><li>窗口大小调整事件</li><li>表单验证（等用户完成输入后再验证）</li></ul><p><strong>代码示例</strong></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">/**</span>\n<span class="line"> * 防抖原理：一定时间内，只有最后一次操作，再过wait毫秒后才执行函数</span>\n<span class="line"> * </span>\n<span class="line"> * @param {Function} func 要执行的回调函数 </span>\n<span class="line"> * @param {Number} wait 延时的时间</span>\n<span class="line"> * @param {Boolean} immediate 是否立即执行 </span>\n<span class="line"> * @return null</span>\n<span class="line"> */</span>\n<span class="line">let timeout = null;</span>\n<span class="line">export function debounce(func, wait = 500, immediate = false) {</span>\n<span class="line">\t// 清除定时器</span>\n<span class="line">\tif (timeout !== null) clearTimeout(timeout);</span>\n<span class="line">\t// 立即执行，此类情况一般用不到</span>\n<span class="line">\tif (immediate) {</span>\n<span class="line">\t\tvar callNow = !timeout;</span>\n<span class="line">\t\ttimeout = setTimeout(function() {</span>\n<span class="line">\t\t\ttimeout = null;</span>\n<span class="line">\t\t}, wait);</span>\n<span class="line">\t\tif (callNow) typeof func === &#39;function&#39; &amp;&amp; func();</span>\n<span class="line">\t} else {</span>\n<span class="line">\t\t// 设置定时器，当最后一次操作后，timeout不会再被清除，所以在延时wait毫秒后执行func回调方法</span>\n<span class="line">\t\ttimeout = setTimeout(function() {</span>\n<span class="line">\t\t\ttypeof func === &#39;function&#39; &amp;&amp; func();</span>\n<span class="line">\t\t}, wait);</span>\n<span class="line">\t}</span>\n<span class="line">}</span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>使用</strong></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">&lt;view class=&quot;debounce&quot; @tap=&quot;$u.debounce(btnAClick, 500)&quot;&gt;&lt;/view&gt;</span>\n<span class="line"></span>\n<span class="line">&lt;script setup&gt;</span>\n<span class="line">const toNext =&gt; {</span>\n<span class="line">...</span>\n<span class="line">}</span>\n<span class="line">...</span>\n<span class="line">debounce(toNext, 500)</span>\n<span class="line">...</span>\n<span class="line">&lt;/script&gt;</span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="节流-throttle" tabindex="-1"><a class="header-anchor" href="#节流-throttle"><span>节流（Throttle）</span></a></h3><p>在一段时间内只允许时间处理函数执行一次，无论事件触发了多少次</p><p><strong>工作原理：</strong></p><ol><li>当事件第一次触发式，执行函数并记录时间</li><li>在指定的时间间隔内，忽略所有后续触发</li><li>时间间隔过后，再次触发是会执行函数并重复上述过程</li></ol><p><strong>典型应用场景：</strong></p><ul><li>鼠标移动事件（当鼠标移动时，每隔一定时间执行一次处理函数）</li><li>滚动事件处理（当用户滚动页面时，每隔一定时间执行一次处理函数）</li><li>防止按钮重复点击</li></ul><p><strong>代码示例</strong></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">/**</span>\n<span class="line"> * 节流原理：在一定时间内，只能触发一次</span>\n<span class="line"> *</span>\n<span class="line"> * @param {Function} func 要执行的回调函数</span>\n<span class="line"> * @param {Number} wait 延时的时间</span>\n<span class="line"> * @param {Boolean} immediate 是否立即执行</span>\n<span class="line"> * @return null</span>\n<span class="line"> */</span>\n<span class="line">let timer;</span>\n<span class="line">let flag;</span>\n<span class="line">export function throttle(func, wait = 500, immediate = true) {</span>\n<span class="line">  if (immediate) {</span>\n<span class="line">    if (!flag) {</span>\n<span class="line">      flag = true</span>\n<span class="line">      // 如果是立即执行，则在wait毫秒内开始时执行</span>\n<span class="line">      typeof func === &#39;function&#39; &amp;&amp; func()</span>\n<span class="line">      timer = setTimeout(() =&gt; {</span>\n<span class="line">        flag = false</span>\n<span class="line">      }, wait)</span>\n<span class="line">    }</span>\n<span class="line">  } else if (!flag) {</span>\n<span class="line">    flag = true</span>\n<span class="line">    // 如果是非立即执行，则在wait毫秒内的结束处执行</span>\n<span class="line">    timer = setTimeout(() =&gt; {</span>\n<span class="line">      flag = false</span>\n<span class="line">      typeof func === &#39;function&#39; &amp;&amp; func()</span>\n<span class="line">    }, wait)</span>\n<span class="line">  }</span>\n<span class="line">}</span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>使用</strong></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">&lt;view class=&quot;throttle&quot; @click=&quot;throttle(handeSave, 1000)&quot;&gt;提交&lt;/view&gt;</span>\n<span class="line"></span>\n<span class="line"></span>\n<span class="line">&lt;script setup&gt;</span>\n<span class="line">const toNext =&gt; {</span>\n<span class="line">...</span>\n<span class="line">}</span>\n<span class="line">...</span>\n<span class="line">throttle(toNext, 500)</span>\n<span class="line">...</span>\n<span class="line">&lt;/script&gt;</span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h3><ul><li><p>如果需要在事件完全停止触发后才执行处理函数，使用防抖。</p></li><li><p>如果需要在时间频繁触发是控制执行频率，使用节流。</p></li><li><p>在实际开发中，可以根据具体需求选择合适的方式。（防止按钮重复点击，也可以给按钮加一个loading状态。）</p></li></ul>',23)]))}]]),t=JSON.parse('{"path":"/blogs/javascript/debounce_throttle.html","title":"防抖与节流","lang":"zh-CN","frontmatter":{"title":"防抖与节流","date":"2025/07/09","tags":["FE","JavaScript"],"categories":["JavaScript"]},"headers":[{"level":3,"title":"防抖（Debounce）","slug":"防抖-debounce","link":"#防抖-debounce","children":[]},{"level":3,"title":"节流（Throttle）","slug":"节流-throttle","link":"#节流-throttle","children":[]},{"level":3,"title":"总结","slug":"总结","link":"#总结","children":[]}],"git":{"createdTime":1752051503000,"updatedTime":1752051503000,"contributors":[{"name":"Lirioing","email":"lirong@xgw66.com","commits":1}]},"filePathRelative":"blogs/javascript/debounce&throttle.md"}')}}]);